in.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'https://wordpress.org/'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US','/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'Usage of the title attribute on the login logo is not recommended for accessibility reasons. Use the link text instead.'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US','/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'Powered by WordPress'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US','/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'Username or Email Address'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US'],'names'=>[],'cmp'=>['WordPress',3]],'Password'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US'],'names'=>[],'cmp'=>['WordPress',3]],'Show password'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US'],'names'=>[],'cmp'=>['WordPress',3]],'Remember Me'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US'],'names'=>[],'cmp'=>['WordPress',3]],'Language'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US','/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'Change'=>['urls'=>['/wp-login.php?lang=ar&interim-login=1&wp_lang=en_US','/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'You have logged in successfully.'=>['urls'=>['/wp-login.php?lang=ar'],'names'=>[],'cmp'=>['WordPress',3]],'Default\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Light\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Modern\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Blue\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Midnight\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Sunrise\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Ectoplasm\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Ocean\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Coffee\\4admin color scheme'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Suggested text:'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Who we are'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Our website address is: %s.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Comments'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Media'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Cookies'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Embedded content from other websites'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Who we share your data with'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you request a password reset, your IP address will be included in the reset email.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'How long we retain your data'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'What rights you have over your data'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Where your data is sent'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Visitor comments may be checked through an automated spam detection service.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'WordPress'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Empty Term.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Blog Home\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Front Page\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Pages\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'All Archives\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Taxonomy\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Attachment Pages'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Displays when a visitor views the dedicated page that exists for any media attachment.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Search Results\\4Template name'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Displays when a visitor performs a search on your website.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Privacy Policy'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Displays your site\'s Privacy Policy page.'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'WordPress &rsaquo; Error'=>['urls'=>['/wp-admin/admin-ajax.php'],'names'=>[],'cmp'=>['WordPress',3]],'Custom Menu'=>['urls'=>['/product/digi-hd-tv-32-inch-led-tv/?lang=ar&vc_editable=true&vc_post_id=13820&_vcnonce=8e732a17c5','/%d8%a7%d9%84%d9%85%d8%b9%d8%a7%d9%8a%d9%86%d8%a9/?lang=ar&vc_editable=true&vc_post_id=3970&_vcnonce=88d6fba3cb','/checkout-2/?lang=ar&vc_editable=true&vc_post_id=61634&_vcnonce=88d6fba3cb'],'names'=>[],'cmp'=>['WordPress',3]],'Visit %s to create your map (Step by step: 1) Find location 2) Click the cog symbol in the lower right corner and select "Share or embed map" 3) On modal window select "Embed map" 4) Copy iframe code and paste it).'=>['urls'=>['/product/digi-hd-tv-32-inch-led-tv/?lang=ar&vc_editable=true&vc_post_id=13820&_vcnonce=8e732a17c5','/%d8%a7%d9%84%d9%85%d8%b9%d8%a7%d9%8a%d9%86%d8%a9/?lang=ar&vc_editable=true&vc_post_id=3970&_vcnonce=88d6fba3cb','/checkout-2/?lang=ar&vc_editable=true&vc_post_id=61634&_vcnonce=88d6fba3cb'],'names'=>[],'cmp'=>['WordPress',3]]]];
